def sim(b, n, m, h, x):
	Need = 0
	Limit = b[0] - 1 + 2 * h
	if Limit > x:
		return False
	for i in range(1, n):
		if Limit + 2 * h <= x:
			Limit += 2 * h
		else:
			Limit = b[i] - 1 + 2 * h
			Need += 1
	return Need < m
for _ in range(int(input())):
	(n, m, h) = map(int, input().split())
	b = []
	for _ in range(n):
		(ai, bi) = map(int, input().split())
		b.append(bi)
	b.sort(reverse=True)
	(lo, hi) = (0, 10 ** 15)
	while lo < hi:
		mid = (lo + hi) // 2
		if sim(b, n, m, h, mid):
			hi = mid
		else:
			lo = mid + 1
	print(lo)
